import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"程序员英语 07：会议、听力与技术表达","description":"通过澄清、复述、状态更新和一分钟技术说明训练工作英语，区分文字演练与真实听说能力。","frontmatter":{"title":"程序员英语 07：会议、听力与技术表达","description":"通过澄清、复述、状态更新和一分钟技术说明训练工作英语，区分文字演练与真实听说能力。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"程序员英语","summary":"通过澄清、复述、状态更新和一分钟技术说明训练工作英语，区分文字演练与真实听说能力。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"程序员英语 06：代码评审与技术说明","link":"/life/english/programmer/review-writing"},"next":{"text":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"程序员英语 06：代码评审与技术说明","link":"/life/english/programmer/review-writing"},"next":{"text":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice"}},"headers":[],"relativePath":"life/english/programmer/listening-speaking.md","filePath":"life/english/programmer/listening-speaking.md"}'),s={name:"life/english/programmer/listening-speaking.md"};function l(r,e,o,p,c,d){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="程序员英语-07-会议、听力与技术表达" tabindex="-1">程序员英语 07：会议、听力与技术表达 <a class="header-anchor" href="#程序员英语-07-会议、听力与技术表达" aria-label="Permalink to &quot;程序员英语 07：会议、听力与技术表达&quot;">​</a></h1><p>技术会议里，最危险的情况往往不是没听懂一个词，而是没有确认就把猜测当成决定。口语训练可以先从三件事开始：说清当前状态、询问缺失信息、复述行动项。</p><h2 id="一次简短的澄清对话" tabindex="-1">一次简短的澄清对话 <a class="header-anchor" href="#一次简短的澄清对话" aria-label="Permalink to &quot;一次简短的澄清对话&quot;">​</a></h2><p>下面是原创脚本，背景是准备升级一个虚构命令行工具：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alex: We can remove the old flag after the next release.</span></span>
<span class="line"><span>Mei: Do you mean the release scheduled for Tuesday?</span></span>
<span class="line"><span>Alex: Yes, but only after we confirm that no supported scripts use it.</span></span>
<span class="line"><span>Mei: So the release alone is not enough. We also need a usage check.</span></span>
<span class="line"><span>Alex: Exactly. I will check the scripts by Monday afternoon.</span></span>
<span class="line"><span>Mei: Thanks. I will keep the flag until we review that result.</span></span></code></pre></div><p>Mei 没有仅复述 Tuesday，而是抓住 <code>only after</code> 带来的额外条件。最后明确了责任人与下一步。若不知道时区，还应补问，而不是把 Monday afternoon 自动解释成本地时间。</p><h2 id="没听懂时-缩小问题" tabindex="-1">没听懂时，缩小问题 <a class="header-anchor" href="#没听懂时-缩小问题" aria-label="Permalink to &quot;没听懂时，缩小问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缺口</th><th>可用表达</th></tr></thead><tbody><tr><td>关键数字</td><td>Did you say thirteen or thirty?</td></tr><tr><td>单位</td><td>Is that value in seconds or milliseconds?</td></tr><tr><td>术语</td><td>What does “drain” mean in this context?</td></tr><tr><td>范围</td><td>Does this apply to existing files as well?</td></tr><tr><td>行动人</td><td>Who will verify the result?</td></tr><tr><td>结论</td><td>Let me confirm: we will keep the old behavior until the check is complete.</td></tr></tbody></table><p><code>Could you repeat that?</code> 很实用，但若只缺一个数字，直接问数字可以减少重复。听到不熟悉的缩写时，可以请对方展开全称，不必假装听懂。</p><h2 id="用四句话做状态更新" tabindex="-1">用四句话做状态更新 <a class="header-anchor" href="#用四句话做状态更新" aria-label="Permalink to &quot;用四句话做状态更新&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I reproduced the import failure with a file that contains a blank line.</span></span>
<span class="line"><span>I am checking whether whitespace-only lines should behave the same way.</span></span>
<span class="line"><span>The expected behavior is not documented, so I need a product decision.</span></span>
<span class="line"><span>After that, I can finish the fix and the regression cases.</span></span></code></pre></div><p>四句话分别是完成项、当前项、阻碍和下一步。没有根据时不要承诺某个完成时间。若估时，应给条件：<code>If we confirm the rule today, I expect to finish the change tomorrow.</code></p><h2 id="真正练听力的方法" tabindex="-1">真正练听力的方法 <a class="header-anchor" href="#真正练听力的方法" aria-label="Permalink to &quot;真正练听力的方法&quot;">​</a></h2><p>选择有原始音频或视频、能核对字幕的短技术材料。可以从 <a href="https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/video_galleries/video-lectures/" target="_blank" rel="noopener noreferrer">MIT 6.042J 视频目录</a> 选择已学过的数学主题，降低概念和语言同时陌生的负担。</p><p>第一遍不看字幕，记录主旨、数字和条件；第二遍打开字幕核对漏听位置；第三遍关闭字幕，用 30～60 秒复述。只截取自己能处理的短段，不要求一次听完一节课。字幕也可能存在错误，关键公式应同时核对课件。</p><p>录音后检查对象和动作是否清楚、数字与单位是否完整、停顿是否影响理解。有同伴时请对方复述听到的行动项。没有真实音频和他人反馈时，本文脚本只能检验文字组织，不能证明听辨、发音或实时交流已经达标。</p><h2 id="练习-把会议内容变成记录" tabindex="-1">练习：把会议内容变成记录 <a class="header-anchor" href="#练习-把会议内容变成记录" aria-label="Permalink to &quot;练习：把会议内容变成记录&quot;">​</a></h2><p>根据开头的对话，写一句决策记录和两个行动项。再说出一个原文没有交代的时间信息。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p>决策：<code>Keep the old flag until the next release is complete and the script-usage check has been reviewed.</code></p><p>行动一：<code>Alex will check supported scripts by Monday afternoon.</code></p><p>行动二：<code>Mei will keep the flag while the team reviews the result.</code></p><p>原文未交代具体日历日期和时区，也未承诺 Monday afternoon 一定能证明所有脚本都不使用旧选项。真实记录应补齐这些缺口。</p></details>`,19)])])}const g=a(s,[["render",l]]);export{u as __pageData,g as default};
